//! "Ashen Keep": the hack-and-slash example game. One complete level: the outer bailey,
//! the courtyard and the great hall with its boss.
//!
//! Models and textures are generated by `tools/make_ashen_assets.py` and embedded here;
//! sounds are synthesised when the project is created; the level is laid out in `build_scene`.

use crate::anim::{Action, Clip, Ease, Marker, Property};
use crate::scene::{
    BodyKind, ColliderShape, LightKind, Physics, PropValue, Scene, ScriptRef, Shape,
};
use glam::Vec3;
use std::collections::{BTreeMap, HashMap};
use std::path::Path;

#[path = "ashen_files.rs"]
mod files;

const SCRIPTS: &[(&str, &str)] = &[
    ("Hero.cryo", include_str!("../template/ashen_scripts/Hero.cryo")),
    ("Enemy.cryo", include_str!("../template/ashen_scripts/Enemy.cryo")),
    ("Boss.cryo", include_str!("../template/ashen_scripts/Boss.cryo")),
    ("ActionCamera.cryo", include_str!("../template/ashen_scripts/ActionCamera.cryo")),
    ("Director.cryo", include_str!("../template/ashen_scripts/Director.cryo")),
    ("Gate.cryo", include_str!("../template/ashen_scripts/Gate.cryo")),
    ("Zone.cryo", include_str!("../template/ashen_scripts/Zone.cryo")),
    ("Shrine.cryo", include_str!("../template/ashen_scripts/Shrine.cryo")),
    ("Potion.cryo", include_str!("../template/ashen_scripts/Potion.cryo")),
    ("Flame.cryo", include_str!("../template/ashen_scripts/Flame.cryo")),
];

pub const SCENE: &str = "scenes/AshenKeep.cryoscene";

/// Writes the whole game into `dir` (which must not already hold a project) and returns the scene path.
pub fn create(dir: &Path) -> Result<String, String> {
    let err = |e: std::io::Error| format!("could not create the example at {}: {e}", dir.display());
    if !crate::project::list_files(dir, crate::project::SCENE_EXT).is_empty() {
        return Err(format!("{} already holds a project; choose an empty folder for Ashen Keep", dir.display()));
    }
    for sub in ["scripts", "scenes", "models", "sounds", "textures"] {
        std::fs::create_dir_all(dir.join(sub)).map_err(err)?;
    }
    for (name, src) in SCRIPTS {
        std::fs::write(dir.join("scripts").join(name), src).map_err(err)?;
    }
    for (name, bytes) in files::FILES {
        std::fs::write(dir.join("models").join(name), bytes).map_err(err)?;
    }
    for (name, wav) in sounds() {
        std::fs::write(dir.join(format!("sounds/{name}.wav")), wav).map_err(err)?;
    }
    let scene = build_scene(dir);
    std::fs::write(dir.join(SCENE), scene.to_json()).map_err(err)?;
    Ok(SCENE.to_string())
}

fn sounds() -> Vec<(&'static str, Vec<u8>)> {
    use crate::audio::synth_wav;
    use std::f32::consts::TAU;
    let tone = |f: f32, t: f32| (t * f * TAU).sin();
    // cheap noise: good enough for whooshes and impacts
    let hiss = |t: f32| ((t * 91_733.0).sin() * 43_758.547).fract() * 2.0 - 1.0;
    let fade = |t: f32, d: f32| (1.0 - t / d).max(0.0);
    vec![
        ("swing", synth_wav(0.22, move |t| hiss(t) * (t / 0.22 * 3.14).sin().powi(2) * tone(900.0 - t * 2500.0, t).abs() * 0.5)),
        ("hit", synth_wav(0.2, move |t| (hiss(t) * 0.6 + tone(150.0, t) * 0.7) * (-t * 22.0).exp())),
        ("block", synth_wav(0.3, move |t| (tone(1900.0, t) + tone(2630.0, t) + hiss(t) * 0.4) * (-t * 14.0).exp() * 0.35)),
        ("hurt", synth_wav(0.3, move |t| (tone(170.0 - t * 200.0, t) + tone(181.0, t)) * (-t * 8.0).exp() * 0.45)),
        ("die", synth_wav(1.2, move |t| tone(220.0 - t * 120.0, t) * fade(t, 1.2) * 0.5 + tone(110.0, t) * fade(t, 1.2) * 0.3)),
        ("roll", synth_wav(0.3, move |t| hiss(t) * fade(t, 0.3) * tone(220.0, t).abs() * 0.4)),
        ("bones", synth_wav(0.5, move |t| hiss(t) * ((t * 38.0).sin() > 0.3) as i32 as f32 * fade(t, 0.5) * 0.5)),
        ("arrow", synth_wav(0.25, move |t| hiss(t) * tone(1400.0 - t * 3000.0, t).abs() * fade(t, 0.25) * 0.45)),
        ("heal", synth_wav(0.7, move |t| (tone(660.0, t) + tone(990.0, t) * (t * 6.0).min(1.0)) * fade(t, 0.7) * 0.3)),
        ("gate", synth_wav(2.6, move |t| (hiss(t) * 0.25 + tone(55.0, t) * 0.5) * ((t * 9.0).sin() * 0.3 + 0.7) * fade(t, 2.6))),
        ("roar", synth_wav(1.5, move |t| (tone(70.0 + (t * 30.0).sin() * 12.0, t) + hiss(t) * 0.35) * (t * 6.0).min(1.0) * fade(t, 1.5) * 0.7)),
        ("slam", synth_wav(0.6, move |t| (tone(48.0, t) + hiss(t) * 0.5 * (-t * 20.0).exp()) * (-t * 6.0).exp())),
        (
            "victory",
            synth_wav(2.4, move |t| {
                let notes = [293.66, 369.99, 440.0, 587.33];
                let i = ((t / 0.3) as usize).min(3);
                (tone(notes[i], t) + tone(notes[i] * 1.5, t) * 0.4) * fade(t, 2.4) * 0.35
            }),
        ),
        (
            // a slow, dark loop: a drone on D with a four-note figure over it
            "music",
            synth_wav(16.0, move |t| {
                let notes = [146.83, 174.61, 130.81, 164.81];
                let n = notes[(t / 4.0) as usize % 4];
                let swell = (t / 16.0 * TAU).sin() * 0.15 + 0.85;
                let beat = ((t % 1.0) * -3.0).exp();
                (tone(73.42, t) * 0.35 + tone(n, t) * 0.2 * beat + tone(n * 2.0, t) * 0.07 + tone(36.71, t) * 0.25) * swell * 0.6
            }),
        ),
    ]
}

/// Lays out the level. `dir` is where the models were written (their sizes are read from there).
pub fn build_scene(dir: &Path) -> Scene {
    let mut s = Scene::empty();
    // a cold, overcast evening: the torches are the only warm light
    s.sky_top = [0.07, 0.09, 0.13];
    s.sky_horizon = [0.40, 0.44, 0.47];
    s.ambient = [0.30, 0.34, 0.42];
    s.fog = 0.021;
    s.gravity = -24.0;

    let mut bounds: HashMap<String, ([f32; 3], [f32; 3])> = HashMap::new();
    let v = Vec3::new;
    let script = |name: &str, props: &[(&str, PropValue)]| {
        let mut map = BTreeMap::new();
        for (k, val) in props {
            map.insert(k.to_string(), val.clone());
        }
        Some(ScriptRef { path: format!("scripts/{name}.cryo"), props: map })
    };
    // A model from models/, with its feet at `pos`, turned `yaw` degrees.
    let mut model = |s: &mut Scene, name: &str, file: &str, pos: Vec3, yaw: f32| -> u64 {
        let b = *bounds.entry(file.to_string()).or_insert_with(|| {
            crate::assets::load_model(&dir.join("models").join(file))
                .map(|m| (m.center.to_array(), m.half.to_array()))
                .unwrap_or(([0.0; 3], [0.5; 3]))
        });
        let id = s.add_mesh(Shape::Cube);
        let e = s.get_mut(id).unwrap();
        e.name = name.into();
        e.position = pos;
        e.rotation = v(0.0, yaw, 0.0);
        let m = e.mesh.as_mut().unwrap();
        m.model = Some(format!("models/{file}"));
        m.model_bounds = Some(b);
        m.color = [1.0; 3];
        m.shininess = 0.08;
        id
    };
    let solid = |s: &mut Scene, id: u64| {
        s.get_mut(id).unwrap().physics = Some(Physics::new(BodyKind::Static, ColliderShape::Box));
        id
    };
    let group = |s: &mut Scene, name: &str| s.add_empty(name);
    let adopt = |s: &mut Scene, parent: u64, id: u64| {
        s.get_mut(id).unwrap().parent = Some(parent);
        id
    };

    // ------------------------------------------------------------ light and mood: dusk
    let sun = s.add_light(LightKind::Directional);
    {
        let e = s.get_mut(sun).unwrap();
        e.name = "Setting Sun".into();
        e.position = v(-30.0, 30.0, 40.0);
        e.rotation = v(-26.0, -52.0, 0.0);
        let l = e.light.as_mut().unwrap();
        l.color = [0.78, 0.83, 0.92];
        l.intensity = 0.95;
        l.shadow_distance = 46.0;
    }
    let sky = s.add_light(LightKind::Directional);
    {
        let e = s.get_mut(sky).unwrap();
        e.name = "Sky Light".into();
        e.position = v(30.0, 30.0, -40.0);
        e.rotation = v(-50.0, 140.0, 0.0);
        let l = e.light.as_mut().unwrap();
        l.color = [0.45, 0.55, 0.9];
        l.intensity = 0.35;
        l.shadows = false;
    }

    // ------------------------------------------------------------ ground
    let world = group(&mut s, "Keep");
    for (name, file, pos) in [
        ("Bailey Ground", "ground_grass.obj", v(0.0, 0.0, 30.0)),
        ("Courtyard Ground", "ground_cobble.obj", v(0.0, 0.0, -16.0)),
        ("Hall Floor", "ground_hall.obj", v(0.0, 0.0, -51.0)),
    ] {
        let id = model(&mut s, name, file, pos, 0.0);
        let m = s.get_mut(id).unwrap().mesh.as_mut().unwrap();
        m.cast_shadow = false;
        if file == "ground_grass.obj" {
            m.color = [0.8, 0.8, 0.8];
        }
        solid(&mut s, id);
        adopt(&mut s, world, id);
    }

    // ------------------------------------------------------------ walls
    let walls = group(&mut s, "Walls");
    let mut wall = |s: &mut Scene, file: &str, x: f32, z: f32, yaw: f32| {
        let id = model(s, "Wall", file, v(x, 0.0, z), yaw);
        solid(s, id);
        adopt(s, walls, id);
    };
    // bailey: a ring of curtain wall around the grass
    for i in 0..5 {
        let z = 8.0 + i as f32 * 12.0;
        wall(&mut s, "wall_12.obj", -20.0, z, 90.0);
        wall(&mut s, "wall_12.obj", 20.0, z, 90.0);
    }
    for x in [-12.0, 0.0, 12.0] {
        wall(&mut s, "wall_12.obj", x, 57.0, 0.0);
    }
    // the gatehouse between bailey and courtyard (z = 2), and the wall beside it
    for side in [-1.0f32, 1.0] {
        wall(&mut s, "pier.obj", side * 4.4, 2.0, 0.0);
        wall(&mut s, "wall_12.obj", side * 12.0, 2.0, 0.0);
        for z in [-4.0, -16.0, -28.0] {
            wall(&mut s, "wall_12.obj", side * 18.5, z, 90.0);
        }
        // front of the great hall (z = -34) and its long sides
        wall(&mut s, "wall_hall.obj", side * 8.6, -34.0, 0.0);
        for z in [-40.0, -52.0, -64.0] {
            wall(&mut s, "wall_hall.obj", side * 13.2, z, 90.0);
        }
        wall(&mut s, "wall_hall.obj", side * 6.0, -68.5, 0.0);
    }
    for (file, z, y) in [("lintel.obj", 2.0, 5.5), ("lintel.obj", -34.0, 5.5)] {
        let id = model(&mut s, "Gate Arch", file, v(0.0, y, z), 0.0);
        solid(&mut s, id);
        adopt(&mut s, walls, id);
    }
    for (x, z) in [(-19.5, 2.0), (19.5, 2.0), (-19.5, -34.0), (19.5, -34.0), (-20.5, 57.5), (20.5, 57.5)] {
        let id = model(&mut s, "Tower", "tower.obj", v(x, 0.0, z), 0.0);
        solid(&mut s, id);
        adopt(&mut s, walls, id);
    }

    // ------------------------------------------------------------ gates
    for (name, z, area) in [("Bailey Gate", 2.0, "bailey"), ("Hall Gate", -34.0, "courtyard")] {
        let id = model(&mut s, name, "portcullis.obj", v(0.0, 0.0, z), 0.0);
        solid(&mut s, id);
        s.get_mut(id).unwrap().script = script("Gate", &[("area", PropValue::Text(area.into()))]);
    }

    // ------------------------------------------------------------ torches, banners, clutter
    let props = group(&mut s, "Props");
    let mut torch = |s: &mut Scene, x: f32, z: f32| {
        let post = model(s, "Torch", "torch.obj", v(x, 0.0, z), 0.0);
        adopt(s, props, post);
        let flame = s.add_mesh(Shape::Sphere);
        {
            let e = s.get_mut(flame).unwrap();
            e.name = "Flame".into();
            e.position = v(x, 2.45, z);
            e.scale = v(0.34, 0.5, 0.34);
            let m = e.mesh.as_mut().unwrap();
            m.color = [1.0, 0.62, 0.2];
            m.unlit = true;
            m.cast_shadow = false;
            e.script = Some(ScriptRef { path: "scripts/Flame.cryo".into(), props: BTreeMap::new() });
        }
        adopt(s, props, flame);
        let light = s.add_light(LightKind::Point);
        {
            let e = s.get_mut(light).unwrap();
            e.name = "Torch Light".into();
            e.position = v(x, 2.9, z);
            let l = e.light.as_mut().unwrap();
            l.color = [1.0, 0.55, 0.22];
            l.intensity = 3.2;
            l.range = 13.0;
        }
        adopt(s, props, light);
    };
    for (x, z) in [
        (-3.4, 5.0), (3.4, 5.0), (-3.4, -1.0), (3.4, -1.0),          // gatehouse
        (-15.0, -10.0), (15.0, -10.0), (-15.0, -24.0), (15.0, -24.0), // courtyard
        (-3.4, -31.0), (3.4, -31.0),                                  // hall door
        (-10.5, -42.0), (10.5, -42.0), (-10.5, -54.0), (10.5, -54.0), (-4.0, -65.0), (4.0, -65.0), // hall
        (-8.0, 40.0), (8.0, 28.0),                                    // bailey path
    ] {
        torch(&mut s, x, z);
    }
    let mut prop = |s: &mut Scene, name: &str, file: &str, x: f32, z: f32, yaw: f32, scale: f32, is_solid: bool| {
        let id = model(s, name, file, v(x, 0.0, z), yaw);
        s.get_mut(id).unwrap().scale = Vec3::splat(scale);
        if is_solid {
            solid(s, id);
        }
        adopt(s, props, id);
    };
    for (x, z, sc) in [(-15.0, 50.0, 1.3), (14.0, 46.0, 1.1), (-16.0, 34.0, 1.5), (16.0, 20.0, 1.2), (-14.0, 12.0, 1.0), (12.0, 9.0, 1.4), (-9.0, 53.0, 0.9), (17.0, 34.0, 1.6)] {
        prop(&mut s, "Pine", "pine.obj", x, z, x * 37.0, sc, false);
    }
    for (x, z, sc, yaw) in [(-10.0, 44.0, 1.0, 20.0), (9.0, 38.0, 0.7, 110.0), (-12.0, 24.0, 1.3, 200.0), (6.0, 14.0, 0.8, 300.0), (13.0, -29.0, 0.9, 40.0)] {
        prop(&mut s, "Rock", "rock.obj", x, z, yaw, sc, true);
    }
    for (x, z, yaw) in [(-12.0, 31.0, 25.0), (11.0, 21.0, -40.0), (-6.0, 45.0, 80.0), (12.0, -13.0, 10.0)] {
        prop(&mut s, "Ruined Wall", "ruin.obj", x, z, yaw, 1.0, true);
    }
    for (x, z) in [(-12.0, -6.0), (-13.1, -6.4), (-12.4, -7.3), (13.0, -20.0), (14.0, -20.6), (-14.0, -30.0), (8.0, -2.0)] {
        prop(&mut s, "Barrel", "barrel.obj", x, z, x * 50.0, 1.0, true);
    }
    for (x, z, yaw) in [(11.0, -6.0, 12.0), (12.3, -5.6, 40.0), (-14.5, -18.0, 5.0), (-9.0, -31.0, 30.0)] {
        prop(&mut s, "Crate", "crate.obj", x, z, yaw, 1.0, true);
    }
    for (x, z, yaw) in [(-7.0, -1.0, 0.0), (7.0, -1.0, 0.0), (-7.0, -31.0, 0.0), (7.0, -31.0, 0.0), (-11.5, -48.0, 90.0), (11.5, -48.0, -90.0), (-11.5, -60.0, 90.0), (11.5, -60.0, -90.0)] {
        prop(&mut s, "Banner", "banner.obj", x, z, yaw, 1.0, false);
    }
    for z in [-40.0, -48.0, -56.0] {
        prop(&mut s, "Pillar", "pillar.obj", -7.5, z, 0.0, 1.0, true);
        prop(&mut s, "Pillar", "pillar.obj", 7.5, z, 0.0, 1.0, true);
    }
    prop(&mut s, "Throne", "throne.obj", 0.0, -66.0, 0.0, 1.0, true);

    // ------------------------------------------------------------ characters
    // Root: collider and script. The model is a child that cancels the root's scale and
    // turns to face where the character is going, so the collider box never rotates.
    let mut character = |s: &mut Scene, name: &str, file: &str, child: &str, pos: Vec3, size: f32, yaw: f32| -> u64 {
        let root = s.add_empty(name);
        {
            let e = s.get_mut(root).unwrap();
            e.position = v(pos.x, 0.92 * size, pos.z);
            e.scale = v(0.8, 1.8, 0.8) * size;
            let mut p = Physics::new(BodyKind::Dynamic, ColliderShape::Box);
            p.friction = 0.0;
            e.physics = Some(p);
        }
        let body = model(s, child, file, v(0.0, -0.5, 0.0), yaw);
        {
            let e = s.get_mut(body).unwrap();
            e.parent = Some(root);
            e.scale = v(1.25, 1.0 / 1.8, 1.25);
            let m = e.mesh.as_mut().unwrap();
            m.animation = "Idle".into();
            m.shininess = 0.35;
        }
        root
    };
    let hero = character(&mut s, "Hero", "knight.gltf", "HeroModel", v(0.0, 0.0, 51.0), 1.0, 0.0);
    {
        let e = s.get_mut(hero).unwrap();
        e.tag = "player".into();
        e.script = script("Hero", &[]);
    }
    let foes = group(&mut s, "Enemies");
    let num = PropValue::Num;
    let mut enemy = |s: &mut Scene, kind: &str, x: f32, z: f32, area: &str| {
        let (file, size, props): (&str, f32, Vec<(&str, PropValue)>) = match kind {
            "archer" => ("archer.gltf", 1.0, vec![("max_health", num(40.0)), ("damage", num(14.0)), ("speed", num(2.6)), ("sight", num(19.0)), ("ranged", PropValue::Bool(true)), ("rest", num(1.4))]),
            "brute" => ("brute.gltf", 1.4, vec![("max_health", num(190.0)), ("damage", num(24.0)), ("speed", num(2.7)), ("reach", num(2.9)), ("windup", num(0.7)), ("rest", num(1.5))]),
            _ => ("skeleton.gltf", 1.0, vec![]),
        };
        let name = match kind {
            "archer" => "Skeleton Archer",
            "brute" => "Bone Brute",
            _ => "Skeleton",
        };
        // no two of the dead are quite the same height
        let size = size * (1.0 + (x * 7.3 + z * 3.1).sin() * 0.06);
        let id = character(s, name, file, "Model", v(x, 0.0, z), size, 180.0);
        let mut props = props;
        props.push(("area", PropValue::Text(area.into())));
        let e = s.get_mut(id).unwrap();
        e.tag = "enemy".into();
        e.parent = Some(foes);
        e.script = script("Enemy", &props);
    };
    // outer bailey: two patrols and an archer by the gate
    for (kind, x, z) in [("skeleton", -3.0, 32.0), ("skeleton", 3.5, 30.0), ("skeleton", 0.0, 27.0), ("skeleton", -6.0, 14.0), ("skeleton", 5.0, 12.0), ("archer", 0.0, 8.0)] {
        enemy(&mut s, kind, x, z, "bailey");
    }
    // courtyard: soldiers, two archers at the back and the brute guarding the hall
    for (kind, x, z) in [("skeleton", -6.0, -10.0), ("skeleton", 6.0, -11.0), ("skeleton", -9.0, -20.0), ("skeleton", 9.0, -21.0), ("archer", -12.0, -27.0), ("archer", 12.0, -27.0), ("brute", 0.0, -27.0)] {
        enemy(&mut s, kind, x, z, "courtyard");
    }
    let boss = character(&mut s, "Ashen Warden", "boss.gltf", "Model", v(0.0, 0.0, -61.0), 1.55, 180.0);
    {
        let e = s.get_mut(boss).unwrap();
        e.tag = "enemy".into();
        e.script = script("Boss", &[]);
    }

    // ------------------------------------------------------------ shrines, potions, zones
    for (x, z) in [(7.0, 47.0), (6.0, -4.0), (-6.0, -37.5)] {
        let id = model(&mut s, "Shrine", "shrine.obj", v(x, 0.0, z), 0.0);
        let mut p = Physics::new(BodyKind::Static, ColliderShape::Box);
        p.is_trigger = true;
        let e = s.get_mut(id).unwrap();
        e.physics = Some(p);
        e.script = script("Shrine", &[]);
        let glow = s.add_light(LightKind::Point);
        let e = s.get_mut(glow).unwrap();
        e.name = "Shrine Glow".into();
        e.position = v(x, 2.4, z);
        let l = e.light.as_mut().unwrap();
        l.color = [0.4, 0.8, 1.0];
        l.intensity = 1.6;
        l.range = 7.0;
    }
    for (x, z) in [(-8.0, 20.0), (10.0, -15.0), (-10.0, -15.0), (9.0, -38.0)] {
        let id = model(&mut s, "Potion", "potion.obj", v(x, 0.5, z), 0.0);
        let mut p = Physics::new(BodyKind::Static, ColliderShape::Sphere);
        p.is_trigger = true;
        let e = s.get_mut(id).unwrap();
        e.scale = Vec3::splat(1.6);
        e.physics = Some(p);
        e.script = script("Potion", &[]);
    }
    let zone = s.add_empty("Hall Threshold");
    {
        let mut p = Physics::new(BodyKind::Static, ColliderShape::Box);
        p.is_trigger = true;
        let e = s.get_mut(zone).unwrap();
        e.position = v(0.0, 2.0, -42.0);
        e.scale = v(24.0, 4.0, 3.0);
        e.physics = Some(p);
        e.script = script("Zone", &[("event", PropValue::Text("boss_wake".into()))]);
    }
    let director = s.add_empty("Director");
    s.get_mut(director).unwrap().script = script("Director", &[]);

    // ------------------------------------------------------------ cameras and the opening shot
    let cam = s.add_camera();
    {
        let e = s.get_mut(cam).unwrap();
        e.name = "Camera".into();
        e.position = v(0.0, 3.4, 57.0);
        e.rotation = v(-14.0, 0.0, 0.0);
        let c = e.camera.as_mut().unwrap();
        c.fov = 62.0;
        c.far = 400.0;
        e.script = script("ActionCamera", &[]);
    }
    let intro_cam = s.add_camera();
    {
        let e = s.get_mut(intro_cam).unwrap();
        e.name = "Intro Camera".into();
        e.position = v(14.0, 26.0, -10.0);
        e.rotation = v(-32.0, 150.0, 0.0);
        e.camera.as_mut().unwrap().fov = 55.0;
        e.camera.as_mut().unwrap().far = 400.0;
    }
    let mut intro = Clip::new("Intro");
    intro.duration = 7.0;
    intro.cutscene = true;
    intro.autoplay = true;
    {
        // from above the hall, over the courtyard, down to the knight at the bailey gate
        let t = intro.track_mut(intro_cam, Property::Position);
        t.set_key(0.0, [10.0, 24.0, -44.0]);
        t.set_key(3.5, [-6.0, 15.0, 6.0]);
        t.set_key(7.0, [0.0, 3.6, 57.5]);
        for k in &mut t.keys {
            k.ease = Ease::Smooth;
        }
        let r = intro.track_mut(intro_cam, Property::Rotation);
        r.set_key(0.0, [-38.0, 200.0, 0.0]);
        r.set_key(3.5, [-22.0, 80.0, 0.0]);
        r.set_key(7.0, [-14.0, 0.0, 0.0]);
    }
    intro.markers.push(Marker { t: 0.0, action: Action::Camera { entity: intro_cam } });
    intro.markers.push(Marker { t: 0.6, action: Action::Broadcast { event: "title".into(), arg: String::new() } });
    intro.markers.push(Marker { t: 6.95, action: Action::Camera { entity: cam } });
    s.animations.push(intro);
    s
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::runtime::{InputState, LogLevel, LogLine, Runtime};

    struct Game {
        scene: Scene,
        rt: Runtime,
        logs: Vec<LogLine>,
        dir: std::path::PathBuf,
    }

    impl Game {
        fn start(tag: &str) -> Game {
            let dir = std::env::temp_dir().join(format!("cryo_ashen_{tag}_{}", std::process::id()));
            std::fs::remove_dir_all(&dir).ok();
            let rel = create(&dir).unwrap();
            let mut scene = Scene::from_json(&std::fs::read_to_string(dir.join(rel)).unwrap()).unwrap();
            let mut logs = vec![];
            let mut rt = Runtime::start(&mut scene, &dir, &mut logs);
            rt.skip_cutscenes(&mut scene, &mut logs);
            let mut g = Game { scene, rt, logs, dir };
            g.run(0.5, &[], &[]);
            g
        }
        fn run(&mut self, seconds: f32, pressed: &[&str], down: &[&str]) {
            let frames = (seconds * 60.0).round().max(1.0) as usize;
            for i in 0..frames {
                let mut input = InputState::default();
                input.down = down.iter().map(|s| s.to_string()).collect();
                if i == 0 {
                    input.pressed = pressed.iter().map(|s| s.to_string()).collect();
                }
                self.rt.update(&mut self.scene, &input, 1.0 / 60.0, &mut self.logs);
            }
            let errs: Vec<_> = self.logs.iter().filter(|l| l.level == LogLevel::Error).map(|l| l.text.clone()).collect();
            assert!(errs.is_empty(), "{errs:?}");
        }
        fn id(&self, name: &str) -> u64 {
            self.scene.find_by_name(name).unwrap_or_else(|| panic!("no entity named {name}"))
        }
        fn pos(&self, name: &str) -> Vec3 {
            self.scene.get(self.id(name)).unwrap().position
        }
        fn bar(&self, name: &str) -> Option<f32> {
            self.rt.bars().iter().find(|b| b.0 == name).map(|b| b.1)
        }
        fn foes(&self, area: &str) -> Vec<u64> {
            self.scene
                .entities
                .iter()
                .filter(|e| e.tag == "enemy")
                .filter(|e| {
                    e.script.as_ref().map(|s| s.props.get("area") == Some(&PropValue::Text(area.into()))).unwrap_or(false)
                })
                .map(|e| e.id)
                .collect()
        }
        fn place_hero(&mut self, x: f32, z: f32) {
            let id = self.id("Hero");
            let e = self.scene.get_mut(id).unwrap();
            e.position.x = x;
            e.position.z = z;
        }
    }

    impl Drop for Game {
        fn drop(&mut self) {
            std::fs::remove_dir_all(&self.dir).ok();
        }
    }

    #[test]
    fn every_model_loads_and_characters_have_their_clips() {
        let dir = std::env::temp_dir().join(format!("cryo_ashen_models_{}", std::process::id()));
        std::fs::remove_dir_all(&dir).ok();
        create(&dir).unwrap();
        let mut loaded = 0;
        for (name, _) in files::FILES {
            if name.ends_with(".obj") || name.ends_with(".gltf") {
                let m = crate::assets::load_model(&dir.join("models").join(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
                assert!(m.triangles > 0);
                if name.ends_with(".gltf") {
                    let sk = m.skeleton.as_ref().unwrap_or_else(|| panic!("{name} has no skeleton"));
                    for clip in ["Idle", "Walk", "Run", "Attack1", "Hit", "Die"] {
                        assert!(sk.clip_index(clip).is_some(), "{name} lacks {clip}");
                    }
                    // feet on the ground, about human height, facing -Z with the weapon on the right
                    assert!((m.center.y - m.half.y).abs() < 0.08, "{name} feet at {}", m.center.y - m.half.y);
                }
                if name.starts_with("wall") || name.starts_with("ground") {
                    assert!(m.subs.iter().any(|s| s.texture.is_some()), "{name} should be textured");
                }
                loaded += 1;
            }
        }
        assert!(loaded >= 25);
        assert!(create(&dir).is_err(), "never overwrites a project");
        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn level_boots_and_the_knight_moves_and_rolls() {
        let mut g = Game::start("boot");
        assert_eq!(g.bar("Health"), Some(1.0));
        assert!(g.rt.hud.starts_with("Clear the outer bailey"), "{}", g.rt.hud);
        assert_eq!(g.foes("bailey").len(), 6);
        assert_eq!(g.foes("courtyard").len(), 7);
        // nobody has noticed the knight yet
        let first = g.foes("bailey")[0];
        let before = g.scene.get(first).unwrap().position;
        g.run(2.0, &[], &[]);
        assert!(g.scene.get(first).unwrap().position.distance(before) < 0.1);
        // W walks away from the camera (north, -Z); Space rolls and costs stamina
        let z0 = g.pos("Hero").z;
        g.run(1.0, &[], &["w"]);
        let walked = z0 - g.pos("Hero").z;
        assert!(walked > 5.0 && walked < 8.0, "walked {walked}");
        let z1 = g.pos("Hero").z;
        g.run(0.6, &["space"], &["w"]);
        assert!(z1 - g.pos("Hero").z > 4.5, "a roll is faster than running");
        assert!(g.bar("Stamina").unwrap() < 0.95);
    }

    #[test]
    fn combat_clears_the_bailey_and_opens_the_gate() {
        let mut g = Game::start("combat");
        // stand in front of the first patrol and let it come
        g.place_hero(0.0, 37.0);
        g.run(3.5, &[], &[]);
        let health = g.bar("Health").unwrap();
        assert!(health < 1.0, "the skeletons hurt a knight who does nothing");
        // fight back: combos until the patrol is gone
        let patrol = g.foes("bailey").len();
        for _ in 0..40 {
            g.run(0.42, &["j"], &[]);
            if g.foes("bailey").len() <= patrol - 3 || g.bar("Health") == Some(0.0) {
                break;
            }
        }
        assert!(g.foes("bailey").len() < patrol, "sword blows kill skeletons");
        // the rest of the area falls (sent directly, to keep the test short)
        let gate_y = g.pos("Bailey Gate").y;
        for id in g.foes("bailey") {
            g.rt.send_for_test(id, "hit", vec![cryo_lang::Value::Num(999.0), cryo_lang::Value::Vec3([0.0, 0.0, 60.0])]);
        }
        g.run(4.5, &[], &[]);
        assert!(g.foes("bailey").is_empty());
        assert!(g.pos("Bailey Gate").y - gate_y > 5.0, "the portcullis rose");
        assert!(g.rt.hud.starts_with("The gate is open"), "{}", g.rt.hud);
        assert!((g.pos("Hall Gate").y).abs() < 0.01, "the second gate waits for the courtyard");
    }

    #[test]
    fn blocking_and_dying_and_respawning() {
        let mut g = Game::start("death");
        g.place_hero(0.0, 37.0);
        g.run(2.0, &[], &[]);
        // a raised shield takes most of the blow
        let open = {
            let before = g.bar("Health").unwrap();
            let hero = g.id("Hero");
            let from = g.pos("Hero") + Vec3::new(0.0, 0.0, -1.0);
            g.rt.send_for_test(hero, "hit", vec![cryo_lang::Value::Num(20.0), cryo_lang::Value::Vec3(from.to_array().map(|c| c as f64))]);
            g.run(0.05, &[], &[]);
            before - g.bar("Health").unwrap()
        };
        assert!(open > 0.15, "an open hit costs 20 health: {open}");
        // killed, the knight comes back at the start with full health
        let hero = g.id("Hero");
        g.rt.send_for_test(hero, "hit", vec![cryo_lang::Value::Num(500.0), cryo_lang::Value::Vec3([0.0, 0.0, 0.0])]);
        g.run(1.0, &[], &[]);
        assert_eq!(g.rt.banner(), Some("YOU DIED"));
        g.run(3.5, &[], &[]);
        assert_eq!(g.bar("Health"), Some(1.0));
        assert!((g.pos("Hero").z - 51.0).abs() < 1.5, "back at the start: {:?}", g.pos("Hero"));
    }

    #[test]
    fn boss_fight_ends_with_the_finisher() {
        let mut g = Game::start("boss");
        let boss = g.id("Ashen Warden");
        let hit = |g: &mut Game, amount: f64| {
            g.rt.send_for_test(boss, "hit", vec![cryo_lang::Value::Num(amount), cryo_lang::Value::Vec3([0.0, 0.0, 0.0])]);
        };
        // asleep: blows do nothing and there is no boss bar
        hit(&mut g, 100.0);
        g.run(0.2, &[], &[]);
        assert_eq!(g.bar("!The Ashen Warden"), None);
        // walking into the hall wakes it
        g.place_hero(0.0, -42.0);
        g.run(2.5, &[], &[]);
        assert_eq!(g.bar("!The Ashen Warden"), Some(1.0));
        assert!(g.rt.hud.starts_with("Defeat the Ashen Warden"));
        let z = g.pos("Ashen Warden").z;
        g.run(1.5, &[], &[]);
        assert!(g.pos("Ashen Warden").z > z + 1.0, "the Warden walks to the knight");
        // it strikes a knight who stands still
        g.run(5.0, &[], &[]);
        assert!(g.bar("Health").unwrap() < 1.0);
        // at zero it kneels and the quick time event appears; failing it revives the Warden
        hit(&mut g, 5000.0);
        g.run(0.3, &[], &[]);
        assert_eq!(g.rt.qte.as_ref().map(|q| q.id.as_str()), Some("execute"));
        g.run(4.5, &[], &[]);
        assert!(g.rt.qte.is_none());
        let back = g.bar("!The Ashen Warden").unwrap();
        assert!((back - 0.25).abs() < 0.01, "back with a quarter of its health: {back}");
        // second chance: mash F
        g.run(2.0, &[], &[]);
        hit(&mut g, 5000.0);
        g.run(0.3, &[], &[]);
        for _ in 0..6 {
            g.run(0.1, &["f"], &[]);
        }
        g.run(2.5, &[], &[]);
        assert_eq!(g.bar("!The Ashen Warden"), None);
        assert_eq!(g.rt.banner(), Some("VICTORY"));
        assert!(g.rt.hud.starts_with("The keep is yours"));
        assert_eq!(g.rt.time_scale(), 1.0);
    }
}
